// OpenAI yanıtını parse et ve her sayfa için ayrı item döndür
const response = $input.first().json;

let content = response?.choices?.[0]?.message?.content;
if (!content) throw new Error('OpenAI boş yanıt döndürdü: ' + JSON.stringify(response));

// Olası markdown code block temizle
content = content.trim();
if (content.startsWith('```')) {
  content = content.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
}

let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  throw new Error('JSON parse hatası. OpenAI yanıtı: ' + content.substring(0, 300));
}

if (!parsed.pages || !Array.isArray(parsed.pages)) {
  throw new Error('OpenAI yanıtında pages dizisi bulunamadı');
}

// Önceki node'dan hikaye değişkenlerini al
const vars = $('Değişkenleri Hazırla').first().json;

console.log(`${parsed.pages.length} sayfa parse edildi. Başlık: ${parsed.title}`);

// Her sayfa için ayrı bir item döndür
return parsed.pages.map(page => ({
  json: {
    story_id:             vars.story_id,
    story_title:          parsed.title,
    page_no:              page.page_number,
    text:                 page.text,
    illustration_prompt:  page.illustration_prompt,
    fal_model:            vars.fal_model,
    fal_endpoint:         `https://fal.run/${vars.fal_model}`,
    photo_url:            vars.photo_url,
    resolution:           vars.resolution,
    child_name:           vars.child_name,
    page_count:           vars.page_count,
    watermark:            vars.watermark,
  }
}));

// Supabase insert yanıtından page_id al
// Parse Sayfaları adımından bağlamı paired item ile geri al
const insertResult = $input.first().json;
const ctx = $('Sayfaları Parse Et').item.json;

// Supabase array ya da tek obje dönebilir
const inserted = Array.isArray(insertResult) ? insertResult[0] : insertResult;
const page_id = inserted?.id ?? null;

if (!page_id) {
  throw new Error(`Sayfa ${ctx.page_no} için Supabase insert ID dönmedi. Yanıt: ` + JSON.stringify(insertResult));
}

console.log(`Sayfa ${ctx.page_no} DB'ye eklendi. ID: ${page_id}`);

const isKontext = ctx.fal_model?.includes('kontext');
const isSchnell = ctx.fal_model?.includes('schnell');

const falBody = {
  prompt: ctx.illustration_prompt,
  image_size: 'landscape_4_3',
  num_images: 1,
  enable_safety_checker: false,
};

if (isKontext) {
  // flux-pro/kontext: karakter tutarlılığı için referans fotoğraf
  if (ctx.photo_url) falBody.image_url = ctx.photo_url;
  falBody.num_inference_steps = 28;
  falBody.guidance_scale = 3.5;
} else if (isSchnell) {
  // Hızlı, düşük kalite (ücretsiz tier)
  falBody.num_inference_steps = 4;
} else {
  // flux/dev — orta kalite
  falBody.num_inference_steps = 20;
  falBody.guidance_scale = 3.5;
}

return [{
  json: {
    page_id,
    story_id:            ctx.story_id,
    page_no:             ctx.page_no,
    fal_endpoint:        ctx.fal_endpoint,
    fal_body:            falBody,
    illustration_prompt: ctx.illustration_prompt,
    photo_url:           ctx.photo_url,
  }
}];

// Aggregate sonrasında pages dizisinden story_id'yi al
const data = $input.first().json;
const pages = data.pages ?? [];

if (!pages.length) throw new Error('Aggregate sonrası sayfa verisi boş');

// Supabase PATCH response içinde story_id alanı var
// Eğer PATCH return=representation ile döndürdüyse, story_id pages[0].story_id'de
const rawPage = Array.isArray(pages[0]) ? pages[0][0] : pages[0];
const story_id = rawPage?.story_id ?? null;

if (!story_id) {
  // Fallback: Sayfaları Parse Et adımından al (eğer paired item erişimi çalışıyorsa)
  throw new Error('story_id bulunamadı. Sayfa verisi: ' + JSON.stringify(rawPage));
}

console.log(`Tüm sayfalar tamamlandı. PDF üretimi başlıyor. story_id: ${story_id}`);
return [{ json: { story_id } }];

const result = $input.first().json;
console.log('✅ Hikaye başarıyla tamamlandı!');
console.log('PDF URL:', result.pdf_url);
return [{ json: { success: true, pdf_url: result.pdf_url, message: 'Hikaye ve PDF başarıyla oluşturuldu.' } }];
